import React, { useState } from 'react';
import { Eye, EyeOff, User } from 'lucide-react';
import { useAuth } from '../contexts/AuthContext';
import { useNavigate, Navigate } from 'react-router-dom';
import logoInicio from '../assets/logoInicio.png';
import '../styles/Login.css';

const Login = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  
  const { login, isAuthenticated } = useAuth();
  const navigate = useNavigate();

  // Si ya está autenticado, redirigir al dashboard
  if (isAuthenticated()) {
    return <Navigate to="/" replace />;
  }

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    if (!email || !password) {
      setError('Por favor, completa todos los campos');
      setLoading(false);
      return;
    }

    try {
      const result = await login(email, password);
      
      if (result.success) {
        console.log('Login exitoso, usuario:', result.user);
        // Redirigir según el rol del usuario
        const userRole = result.user.roles && result.user.roles.length > 0 
          ? result.user.roles[0].name 
          : 'General';
        
        console.log('Rol del usuario:', userRole);
        
        switch (userRole) {
          case 'Admin':
            navigate('/');
            break;
          case 'Tecnico':
            navigate('/tecnico');
            break;
          case 'Coordinador':
            navigate('/');
            break;
          case 'General':
          default:
            navigate('/');
        }
      } else {
        console.error('Error de login:', result);
        // Asegurar que el error siempre sea una string
        let errorMessage = 'Error en las credenciales';
        if (typeof result.error === 'string') {
          errorMessage = result.error;
        } else if (typeof result.error === 'object' && result.error.mensaje) {
          errorMessage = result.error.mensaje;
        } else if (typeof result.error === 'object') {
          errorMessage = JSON.stringify(result.error);
        }
        setError(errorMessage);
      }
    } catch (error) {
      console.error('Error inesperado en login:', error);
      // Asegurar que el error siempre sea una string
      let errorMessage = 'Error inesperado';
      if (typeof error === 'string') {
        errorMessage = error;
      } else if (error.message) {
        errorMessage = error.message;
      } else {
        errorMessage = error.toString();
      }
      setError(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  const togglePasswordVisibility = () => {
    setShowPassword(!showPassword);
  };

  return (
    <div className="login-container">
      <div className="login-card">
        <div className="login-panels">
          <div className="left-panel">
            <div className="central-logo">
              <img src={logoInicio} alt="SIGESA" className="main-logo-image" />
            </div>
                     
            <div className="info-section">
              <p className="organization">DUEA UMSS</p>
              <p className="system-name">Sistema de Gestión de Acreditación (SIGESA)</p>
            </div>
          </div>

          <div className="right-panel">

            <div className="form-container">
              <h2 className="login-title">Iniciar Sesión</h2>
              <div style={{
                width: '120px',
                height: '120px',
                background: 'linear-gradient(135deg, rgba(255, 255, 255, 0.2) 0%, rgba(255, 255, 255, 0.05) 100%)',
                borderRadius: '50%',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                marginBottom: '2.5rem',
                border: '2px solid rgba(255, 255, 255, 0.2)',
                boxShadow: '0 20px 40px -6px rgba(0, 0, 0, 0.25)',
                backdropFilter: 'blur(4px)',
                color: 'rgba(255, 255, 255, 0.8)'
              }}>
                <User size={50} />
              </div>

              <form onSubmit={handleSubmit} className="login-form">
                {error && (
                  <div style={{
                    background: 'rgba(239, 68, 68, 0.1)',
                    border: '1px solid rgba(239, 68, 68, 0.3)',
                    borderRadius: '0.5rem',
                    padding: '0.75rem',
                    marginBottom: '1rem',
                    color: '#fca5a5',
                    fontSize: '0.875rem',
                    textAlign: 'center'
                  }}>
                    {error}
                  </div>
                )}

                <div className="input-group">
                  <label className="input-label">
                    Correo Electrónico:
                  </label>
                  <input
                    type="email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    className="form-input"
                    placeholder="tu.correo@ejemplo.com"
                    required
                    disabled={loading}
                  />
                </div>

                <div className="input-group">
                  <label className="input-label">
                    Contraseña:
                  </label>
                  <div className="password-input-container">
                    <input
                      type={showPassword ? 'text' : 'password'}
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      className="form-input password-input"
                      placeholder="••••••••"
                      required
                      disabled={loading}
                    />
                    <button
                      type="button"
                      onClick={togglePasswordVisibility}
                      className="password-toggle"
                      disabled={loading}
                    >
                      {showPassword ? <EyeOff size={22} /> : <Eye size={22} />}
                    </button>
                  </div>
                </div>

                <button 
                  type="submit" 
                  className="submit-button"
                  disabled={loading}
                  style={{
                    opacity: loading ? 0.7 : 1,
                    cursor: loading ? 'not-allowed' : 'pointer'
                  }}
                >
                  {loading ? 'Iniciando sesión...' : 'Iniciar Sesión'}
                </button>
              </form>

            {/*  <button className="forgot-password">
                ¿Olvidaste tu contraseña? Recuperar
              </button> */} 
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;